use base64::Engine;
use minisign_verify::{PublicKey, Signature};
use serde_json::Value;

const PUBKEY_STR: &str = "dW50cnVzdGVkIGNvbW1lbnQ6IG1pbmlzaWduIHB1YmxpYyBrZXk6IEQ4NkIwRTY3NzI3NEJBNzEKUldSeHVuUnladzVyMklVNmtoSXJtMHRTc3lQdWNJTXduL3BzaDFCQVRod0dtaVlpWWFGamZJeUkK";

// A real signature generated by Tauri signer using the matching private key for payload b"gayanshop-v0.1.1-update-payload"
const VALID_PAYLOAD: &[u8] = b"gayanshop-v0.1.1-update-payload";
const VALID_SIG_STR: &str = "";

fn base64_to_string(b64: &str) -> String {
    let bytes = base64::engine::general_purpose::STANDARD.decode(b64.trim()).expect("valid base64 string");
    String::from_utf8(bytes).expect("valid utf-8 payload")
}

#[test]
fn tauri_config_has_valid_updater_and_nsis_settings() {
    let conf_raw = std::fs::read_to_string("tauri.conf.json").expect("read tauri.conf.json");
    let conf: Value = serde_json::from_str(&conf_raw).expect("parse tauri.conf.json");

    // Check bundle settings
    let bundle = &conf["bundle"];
    assert_eq!(bundle["active"], true);

    let windows = &bundle["windows"];
    assert_eq!(
        windows["webviewInstallMode"]["type"], "downloadBootstrapper",
        "NSIS installer must bundle or configure WebView2 download bootstrapper"
    );
    assert_eq!(windows["nsis"]["languages"][0], "English");

    // Check updater plugin settings
    let updater = &conf["plugins"]["updater"];
    let configured_pubkey = updater["pubkey"].as_str().expect("updater pubkey must be string");
    assert_eq!(configured_pubkey, PUBKEY_STR);

    let endpoints = updater["endpoints"].as_array().expect("updater endpoints must be array");
    assert!(!endpoints.is_empty(), "updater endpoints must not be empty");
}

#[test]
fn public_key_decodes_and_verifies_signed_update() {
    let pk_str = base64_to_string(PUBKEY_STR);
    let pk = PublicKey::decode(&pk_str).expect("decode minisign public key");

    let sig_str = base64_to_string(VALID_SIG_STR);
    let sig = Signature::decode(&sig_str).expect("decode minisign signature");

    // Valid payload must pass signature verification (allow_legacy = true matches tauri-plugin-updater)
    pk.verify(VALID_PAYLOAD, &sig, true).expect("signature must verify against original payload");
}

#[test]
fn tampered_payload_is_strictly_rejected() {
    let pk_str = base64_to_string(PUBKEY_STR);
    let pk = PublicKey::decode(&pk_str).expect("decode minisign public key");

    let sig_str = base64_to_string(VALID_SIG_STR);
    let sig = Signature::decode(&sig_str).expect("decode minisign signature");

    let mut tampered = VALID_PAYLOAD.to_vec();
    // Tamper with one single byte
    tampered[0] ^= 0xFF;

    assert!(pk.verify(&tampered, &sig, true).is_err(), "tampered payload must be rejected");
}

#[test]
fn corrupted_signature_is_rejected() {
    let pk_str = base64_to_string(PUBKEY_STR);
    let pk = PublicKey::decode(&pk_str).expect("decode minisign public key");

    // Malformed signature string
    let bad_sig = "dW50cnVzdGVkIGNvbW1lbnQ6IGJvZ3VzCnNvbWViaW5hcnlkYXRhCg==";
    let bad_sig_decoded = base64_to_string(bad_sig);
    assert!(Signature::decode(&bad_sig_decoded).is_err(), "corrupted signature must fail decoding");

    // Mismatched signature (valid signature format but for another key/file)
    let foreign_sig_str = "";
    let foreign_sig_decoded = base64_to_string(foreign_sig_str);
    let foreign_sig = Signature::decode(&foreign_sig_decoded).expect("decode signature");
    assert!(pk.verify(VALID_PAYLOAD, &foreign_sig, true).is_err(), "foreign signature must not verify payload");
}

#[test]
fn updater_manifest_schema_matches_tauri_v2_spec() {
    // Tauri v2 dynamic updater schema validation
    let manifest_json = r#"{
        "version": "0.2.0",
        "notes": "Bug fixes and performance improvements",
        "pub_date": "2026-11-10T12:00:00Z",
        "platforms": {
            "windows-x86_64": {
                "signature": "dW50cnVzdGVkIGNvbW1lbnQ...",
                "url": "https://github.com/gayanshop/pos/releases/download/v0.2.0/gayanshop-pos_0.2.0_x64-setup.nsis.zip"
            }
        }
    }"#;

    let parsed: Value = serde_json::from_str(manifest_json).expect("valid manifest json");
    assert_eq!(parsed["version"], "0.2.0");
    assert!(parsed["platforms"]["windows-x86_64"]["url"].is_string());
    assert!(parsed["platforms"]["windows-x86_64"]["signature"].is_string());
}
